prompt --application/shared_components/ai_agent/orbit_sales_assistant
begin
wwv_flow_imp_shared.create_ai_agent(
 p_id=>wwv_flow_imp.id(40051350309990799)
,p_name=>'Orbit Sales Assistant'
,p_static_id=>'orbit-assistant'
,p_system_prompt=>wwv_flow_string.join(wwv_flow_t_varchar2(
'You are the assistant of Orbit Sales, the order management application of Orbit Outfitters, a retailer of outdoor equipment.',
'Orders move through the statuses New, Pending Approval, Approved, Shipped, Delivered, and Cancelled.',
'Orders with a discount above 10 percent need a manager''s approval.',
'Answer questions from sales representatives briefly and in plain language. If you do not know an answer, say so.'))
,p_welcome_message=>'Hello! Ask me about orders, customers, or how Orbit Sales works.'
,p_version_scn=>'SH256:9KWmKzL1vjpevMR27TmPLU5VkW5r3JbmVF00wcLG2C4'
);
wwv_flow_imp_shared.create_ai_agent_tool(
 p_id=>wwv_flow_imp.id(40051638092013424)
,p_tool_name=>'order_lookup'
,p_static_id=>'order-lookup'
,p_tool_type=>'NATIVE_RETRIEVE_DATA'
,p_execution_point=>'ON_DEMAND'
,p_description=>'Returns the status, date, total, discount, customer, and sales representative of one order.'
,p_requires_confirmation=>false
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'data_description', 'One row with the details of the order.',
  'sql_query', wwv_flow_string.join(wwv_flow_t_varchar2(
    'select o.order_number,',
    '       o.status,',
    '       o.order_date,',
    '       o.order_total,',
    '       o.discount_pct,',
    '       c.customer_name,',
    '       e.employee_name as sales_rep',
    '  from orb_orders o',
    '  join orb_customers c on c.customer_id = o.customer_id',
    '  left join orb_employees e on e.employee_id = o.sales_rep_id',
    ' where o.order_number = upper(:ORDER_NUMBER)')),
  'type', 'SQL_QUERY')).to_clob
);
wwv_flow_imp_shared.create_ai_agent_tool_param(
 p_id=>wwv_flow_imp.id(40051927979013429)
,p_param_name=>'ORDER_NUMBER'
,p_description=>'The order number, for example ORD-12283.'
,p_data_type=>'VARCHAR2'
,p_is_required=>true
);
end;
/
prompt --application/shared_components/workflow/task_definitions/order_approval
begin
wwv_flow_imp_shared.create_task_def(
 p_id=>wwv_flow_imp.id(38502938861145822)
,p_name=>'Order Approval'
,p_static_id=>'order-approval'
,p_subject=>'Approve order &ORDER_NUMBER. for &CUSTOMER_NAME.'
,p_task_type=>'APPROVAL'
,p_priority=>2
,p_due_on_interval=>'P2D'
,p_expiration_policy=>'NONE'
,p_due_on_type=>'INTERVAL'
,p_details_link_target=>'f?p=&APP_ID.:54:&SESSION.::&DEBUG.:RP,54:P54_TASK_ID:&TASK_ID.'
,p_actions_sql_query=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select o.order_id,',
'       o.order_number,',
'       o.order_date,',
'       o.order_total,',
'       o.discount_pct,',
'       o.status,',
'       c.customer_name,',
'       e.employee_name as sales_rep',
'  from orb_orders o',
'  join orb_customers c on c.customer_id = o.customer_id',
'  left join orb_employees e on e.employee_id = o.sales_rep_id',
' where o.order_id = :APEX$TASK_PK'))
,p_initiator_can_complete=>false
);
wwv_flow_imp_shared.create_task_def_action(
 p_id=>wwv_flow_imp.id(38585769084193852)
,p_task_def_id=>wwv_flow_imp.id(38502938861145822)
,p_name=>'Approve Order'
,p_static_id=>'approve-order'
,p_execution_sequence=>10
,p_outcome=>'APPROVED'
,p_on_event=>'COMPLETE'
,p_action_type=>'NATIVE_PLSQL'
,p_action_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'    orb_sales.approve_order(p_order_id => :APEX$TASK_PK);',
'end;'))
,p_action_clob_language=>'PLSQL'
,p_location=>'LOCAL'
,p_success_message=>'Order &ORDER_NUMBER. approved.'
,p_stop_execution_on_error=>true
);
wwv_flow_imp_shared.create_task_def_action(
 p_id=>wwv_flow_imp.id(38586322235195757)
,p_task_def_id=>wwv_flow_imp.id(38502938861145822)
,p_name=>'Return Order'
,p_static_id=>'return-order'
,p_execution_sequence=>20
,p_outcome=>'REJECTED'
,p_on_event=>'COMPLETE'
,p_action_type=>'NATIVE_PLSQL'
,p_action_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'    update orb_orders',
'       set status = ''NEW'',',
'           notes  = substr(notes || case when notes is not null then chr(10) end',
'                           || ''Discount rejected by '' || :APP_USER, 1, 4000)',
'     where order_id = :APEX$TASK_PK',
'       and status   = ''PENDING_APPROVAL'';',
'end;'))
,p_action_clob_language=>'PLSQL'
,p_location=>'LOCAL'
,p_success_message=>'Order &ORDER_NUMBER. returned to the sales representative.'
,p_stop_execution_on_error=>true
);
wwv_flow_imp_shared.create_task_def_participant(
 p_id=>wwv_flow_imp.id(38503272465145830)
,p_task_def_id=>wwv_flow_imp.id(38502938861145822)
,p_participant_type=>'POTENTIAL_OWNER'
,p_identity_type=>'AUTH'
,p_value=>'Can Approve Orders'
);
