prompt --application/shared_components/email/templates/approval_reminder
begin
wwv_flow_imp_shared.create_email_template(
 p_id=>wwv_flow_imp.id(40045610501741651)
,p_name=>'Approval Reminder'
,p_static_id=>'approval-reminder'
,p_version_number=>2
,p_subject=>'Reminder: order #ORDER_NUMBER# is waiting for approval'
,p_html_body=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Order <strong>#ORDER_NUMBER#</strong> for #CUSTOMER_NAME# is waiting for approval.</p>',
'<p>Order total: #ORDER_TOTAL# &middot; Discount: #DISCOUNT_PCT#%</p>',
'<p>Please review it in <strong>My Approvals</strong> in Orbit Sales.</p>'))
,p_html_header=>'<b>Orbit Outfitters</b>'
,p_html_footer=>'Orbit Sales &middot; automatic reminder'
,p_text_template=>wwv_flow_string.join(wwv_flow_t_varchar2(
'Order #ORDER_NUMBER# for #CUSTOMER_NAME# is waiting for approval.',
'Order total: #ORDER_TOTAL#, discount: #DISCOUNT_PCT#%',
'Please review it in My Approvals in Orbit Sales.'))
,p_version_scn=>'SH256:uYrFX6JRBrHVtkk0mrVeNcE7KW80pIkjuYyvJJiKbtU'
);
end;
/
prompt --application/shared_components/automations/remind_pending_approvals
begin
wwv_flow_imp_shared.create_automation(
 p_id=>wwv_flow_imp.id(40047782970797536)
,p_name=>'Remind Pending Approvals'
,p_static_id=>'remind-pending-approvals'
,p_trigger_type=>'POLLING'
,p_polling_interval=>'FREQ=DAILY;INTERVAL=1;BYHOUR=8;BYMINUTE=0'
,p_polling_status=>'DISABLED'
,p_result_type=>'ROWS'
,p_location=>'LOCAL'
,p_query_type=>'SQL'
,p_query_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select o.order_id,',
'       o.order_number,',
'       c.customer_name,',
'       to_char(o.order_total, ''FM$999G999G990D00'') as order_total,',
'       o.discount_pct',
'  from orb_orders o',
'  join orb_customers c on c.customer_id = o.customer_id',
' where o.status = ''PENDING_APPROVAL'''))
,p_pk_column_name=>'ORDER_ID'
,p_commit_each_row=>false
,p_error_handling_type=>'ABORT'
);
wwv_flow_imp_shared.create_automation_action(
 p_id=>wwv_flow_imp.id(40048523391800736)
,p_automation_id=>wwv_flow_imp.id(40047782970797536)
,p_name=>'Send Reminder'
,p_static_id=>'send-reminder'
,p_execution_sequence=>20
,p_action_type=>'NATIVE_SEND_EMAIL'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'email_template_id', wwv_flow_imp.id(40045610501741651),
  'escape_body_substitutions', 'HTML',
  'from', 'orbit-sales@orbit-outfitters.example',
  'placeholder_values', wwv_flow_string.join(wwv_flow_t_varchar2(
    '{',
    '    "ORDER_NUMBER":"&ORDER_NUMBER.",',
    '    "CUSTOMER_NAME":"&CUSTOMER_NAME.",',
    '    "ORDER_TOTAL":"&ORDER_TOTAL.",',
    '    "DISCOUNT_PCT":"&DISCOUNT_PCT."',
    '}')),
  'send_immediately', 'N',
  'to', 'approvals@orbit-outfitters.example')).to_clob
,p_location=>'LOCAL'
,p_stop_execution_on_error=>true
);
end;
